queries.initial_sql:
SELECT SUM(CASE WHEN T1.major_name = 'Finance' THEN 1 ELSE 0 END) / 
       SUM(CASE WHEN T1.major_name = 'Physics' THEN 1 ELSE 0 END) AS ratio
FROM major AS T1;

queries.final_sql:
SELECT SUM(CASE WHEN T1.major_name = 'Finance' THEN 1 ELSE 0 END) / 
       SUM(CASE WHEN T1.major_name = 'Physics' THEN 1 ELSE 0 END) AS ratio
FROM major AS T1;

queries.initial_sql:
SELECT ID
FROM Patient
WHERE SEX = 'F' AND YEAR(Birthday) = 1964 AND Admission = '+';

queries.final_sql:
SELECT ID
FROM Patient
WHERE SEX = 'F' AND strftime('%Y', Birthday) = '1964' AND Admission = '+';

